{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city looms under a bruised sunset.",
      "visual_description": "Collapsed towers and torn royal banners frame the skyline; the glass diver stands at the edge of a broken plaza, helmet reflecting the dying light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unfolds a tattered map on a fallen pillar.",
      "visual_description": "Mara the cartographer traces a route with ink-stained fingers; behind her, the oracle lamp flickers on a stone, casting a single eye of flame.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts ahead through a cracked archway.",
      "visual_description": "The small clockwork fox peers into a dark alley, tail key-winding slowly; its blue glass eyes glow as it moves.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "At the castle gates, the sleeping tax collector snores on a ledger.",
      "visual_description": "The tax collector slumps against the massive iron gates, stamped papers stuck to his sleeves, oblivious to the rescue party's approach.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye widens as it speaks; beyond, a spiraling tower is wrapped in thorny magic, its door pulsing with runes.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a shattered window into the tower.",
      "visual_description": "The glass diver steps into a mirror-like surface on a broken window pane, body distorting as he passes through into a dark hall.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara marks the map as the fox returns with a scrap of cloth.",
      "visual_description": "Mara adds a cross to her map while the tin fox drops a torn banner fragment; the oracle lamp watches silently.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the tower, the glass diver finds a locked magic door.",
      "visual_description": "A door covered in shifting glyphs stands before the glass diver; his reflection in the metal handle shows a faint blue glow.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector wakes briefly, mumbles, and falls back asleep.",
      "visual_description": "He lifts his head, blinks at the rescue party, then buries his face in the ledger again; papers flutter around him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox leads the group through a hidden passage beneath the old stables.",
      "visual_description": "The fox's tail glows, illuminating a dusty tunnel lined with cobwebs and forgotten royal crates.",
      "characters": ["tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp reveals the tower's secret: a mirror key.",
      "visual_description": "The lamp's flame casts a shadow that points to a mirror shard hidden in a stone niche; the glass diver reaches for it.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "With the mirror key, the glass diver unlocks the magic door.",
      "visual_description": "He inserts the shard into a slot in the door; the glyphs realign and the door swings open into a chamber of floating dust motes.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The chamber holds a trapped figure bound in light.",
      "visual_description": "A humanoid shape is cocooned in luminous threads on a pedestal; the glass diver approaches carefully.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara and the tin fox find the tower's base entrance unguarded.",
      "visual_description": "The cartographer and fox step through a broken portcullis, the fox's ears twitching at distant metal clanks.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver cuts the light-threads with a glass shard, freeing the captive.",
      "visual_description": "He uses a piece of his helmet's edge to sever the threads; the captive falls into his arms, gasping.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The rescue party reunites at the bridge, the sleeping tax collector still snoring at the gate.",
      "visual_description": "Mara, the oracle lamp, the tin fox, the glass diver, and the freed captive rush onto a stone bridge over a dry moat; the tax collector remains distant.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to crumble as magical backlash erupts from the tower.",
      "visual_description": "Cracks spider across the bridge stones; a shockwave of purple energy bursts from the tower behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The party reaches the far side as the bridge collapses into the ravine.",
      "visual_description": "They leap to safety as the bridge falls; the glass diver's helmet reflects the settling dust and the distant city ruins.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ],
  "gate_token": "_Xq0wp2v0Npfkp_rrYwe8A"
}

